@import "tailwindcss";

@theme {
  --font-heading: "Atkinson Hyperlegible Next", sans-serif;
  --font-sans: "Lexend", sans-serif;
  --font-label: "Lexend", sans-serif;
  --font-mono: "Roboto Mono", monospace;

  --color-background: var(--background);
  --color-on-background: var(--on-background);
  --color-surface: var(--surface);
  --color-on-surface: var(--on-surface);
  --color-on-surface-variant: var(--on-surface-variant);
  --color-surface-container: var(--surface-container);
  --color-surface-variant: var(--surface-variant);
  --color-outline: var(--outline);
  --color-outline-variant: var(--outline-variant);

  --color-primary: var(--primary);
  --color-on-primary: var(--on-primary);
  --color-primary-container: var(--primary-container);
  --color-on-primary-container: var(--on-primary-container);

  --color-secondary: var(--secondary);
  --color-on-secondary: var(--on-secondary);
  --color-secondary-container: var(--secondary-container);
  --color-on-secondary-container: var(--on-secondary-container);

  --color-tertiary: var(--tertiary);
  --color-on-tertiary: var(--on-tertiary);
  --color-tertiary-container: var(--tertiary-container);
  --color-on-tertiary-container: var(--on-tertiary-container);

  --color-error: var(--error);
  --color-on-error: var(--on-error);
  --color-error-container: var(--error-container);
  --color-on-error-container: var(--on-error-container);

  --color-warning: var(--warning);
  --color-on-warning: var(--on-warning);
  --color-warning-container: var(--warning-container);
  --color-on-warning-container: var(--on-warning-container);

  --color-success: var(--success);
  --color-on-success: var(--on-success);
  --color-success-container: var(--success-container);
  --color-on-success-container: var(--on-success-container);

  --color-neutral: var(--neutral);
  --color-on-neutral: var(--on-neutral);
  --color-neutral-container: var(--neutral-container);
  --color-on-neutral-container: var(--on-neutral-container);

  --border-width-default: 1px;
  --border-width-emphasis: 2px;
  --border-width-accent: 4px;
  --border-default: 1px;
  --border-emphasis: 2px;
  --border-accent: 4px;

  --radius: 0.5rem;
  --radius-none: 0px;
  --radius-sm: 0.25rem;
  --radius-default: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-full: 9999px;

  --shadow-ambient: var(--shadow-ambient);
  --shadow-ambient-hover: var(--shadow-ambient-hover);
  --shadow-modal: var(--shadow-modal);

  /* Motion Tokens */
  --duration-stagger: 40ms;
  --duration-micro: 80ms;
  --duration-quick: 150ms;
  --duration-fast: 250ms;
  --duration-medium: 350ms;
  --duration-slow: 400ms;
  --duration-very-slow: 500ms;
  --duration-emphasis: 500ms;

  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-in-out: ease-in-out;
  --ease-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --ease-bounce-strong: cubic-bezier(0.34, 3.85, 0.64, 1);

  --scale-large: 0.96;
  --scale-medium: 0.97;
  --scale-small: 0.98;
  --scale-tiny: 0.99;

  --distance-micro: 4px;
  --distance-small: 6px;
  --distance-base: 8px;
  --distance-medium: 12px;
  --distance-roomy: 16px;

  --blur-small: 2px;
  --blur-medium: 3px;
}

:root {
  --font-mono: "Roboto Mono", monospace;
  --background: #F6F7FB;
  --on-background: #1a1c1e;
  --surface: #ffffff;
  --on-surface: #1a1c1e;
  --on-surface-variant: #434656;
  --surface-container: #EEF3FF;
  --surface-variant: #DCE6FA;
  --outline: #737688;
  --outline-variant: #C4D5F8;
  --primary: #0052FF;
  --on-primary: #ffffff;
  --primary-container: #dce6ff;
  --on-primary-container: #1a1c1e;
  --secondary: #00796B;
  --on-secondary: #ffffff;
  --secondary-container: #e0f2f1;
  --on-secondary-container: #1a1c1e;
  --tertiary: #F9A825;
  --on-tertiary: #1a1c1e;
  --tertiary-container: #fff0c2;
  --on-tertiary-container: #1a1c1e;
  --error: #ba1a1a;
  --on-error: #ffffff;
  --error-container: #ffdad6;
  --on-error-container: #1a1c1e;
  --warning: #8a5200;
  --on-warning: #ffffff;
  --warning-container: #ffe0b3;
  --on-warning-container: #1a1c1e;
  --success: #146c2e;
  --on-success: #ffffff;
  --success-container: #c8f5ce;
  --on-success-container: #1a1c1e;

  --neutral: #1a1c1e;
  --on-neutral: #ffffff;
  --neutral-container: #DCE6FA;
  --on-neutral-container: #1a1c1e;

  /* Layered Ambient & Modal Shadows (Umbra + Penumbra) */
  --shadow-ambient: 0 1px 3px rgba(26, 28, 30, 0.04), 0 4px 12px rgba(26, 28, 30, 0.06);
  --shadow-ambient-hover: 0 2px 4px rgba(26, 28, 30, 0.04), 0 8px 20px rgba(26, 28, 30, 0.08);
  --shadow-modal: 0 2px 6px rgba(26, 28, 30, 0.04), 0 8px 20px rgba(26, 28, 30, 0.06), 0 20px 48px rgba(26, 28, 30, 0.12);

  /* Motion Tokens */
  --duration-stagger: 40ms;
  --duration-micro: 80ms;
  --duration-quick: 150ms;
  --duration-fast: 250ms;
  --duration-medium: 350ms;
  --duration-slow: 400ms;
  --duration-very-slow: 500ms;
  --duration-emphasis: 500ms;

  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-in-out: ease-in-out;
  --ease-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --ease-bounce-strong: cubic-bezier(0.34, 3.85, 0.64, 1);

  --scale-large: 0.96;
  --scale-medium: 0.97;
  --scale-small: 0.98;
  --scale-tiny: 0.99;

  --distance-micro: 4px;
  --distance-small: 6px;
  --distance-base: 8px;
  --distance-medium: 12px;
  --distance-roomy: 16px;

  --blur-small: 2px;
  --blur-medium: 3px;
}

/* Border Width Token Utility Classes */
.border-default {
  border-width: 1px;
}

.border-emphasis {
  border-width: 2px;
}

.border-accent {
  border-width: 4px;
}

/* Material Symbols icon styling helper */
.material-symbols-outlined {
  font-family: 'Material Symbols Outlined';
  font-weight: normal;
  font-style: normal;
  font-size: 24px;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-smoothing: antialiased;
}

/* Accessible high-visibility focus ring compatible with forced-colors mode */
*:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* Streamlined focus integration for form controls: merges border and focus ring to prevent double-box artifacts */
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  border-color: var(--primary);
  outline: 2px solid var(--primary);
  outline-offset: 0px;
}

button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* Reduced motion preference */
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Motion & Transition Utilities */
@utility duration-instant {
  transition-duration: var(--duration-instant);
  animation-duration: var(--duration-instant);
}

@utility duration-quick {
  transition-duration: var(--duration-quick);
  animation-duration: var(--duration-quick);
}

@utility duration-moderate {
  transition-duration: var(--duration-moderate);
  animation-duration: var(--duration-moderate);
}

@utility duration-deliberate {
  transition-duration: var(--duration-deliberate);
  animation-duration: var(--duration-deliberate);
}

@utility duration-complex {
  transition-duration: var(--duration-complex);
  animation-duration: var(--duration-complex);
}

@utility stroke-dashoffset-0 {
  stroke-dashoffset: 0;
}

@utility animate-badge-pop {
  animation: badge-pop-in var(--duration-very-slow, 500ms) cubic-bezier(0.34, 1.36, 0.64, 1) both;
}

@utility animate-error-shake {
  animation: error-shake 250ms cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
}

@utility animate-text-reveal {
  animation: text-reveal-rise var(--duration-very-slow, 500ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-step-forward {
  animation: step-slide-forward var(--duration-fast, 250ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-step-backward {
  animation: step-slide-backward var(--duration-fast, 250ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-roll-up {
  animation: roll-up 250ms cubic-bezier(0, 0, 0.2, 1) both;
}

@utility animate-roll-down {
  animation: roll-down 250ms cubic-bezier(0, 0, 0.2, 1) both;
}

@utility animate-check-pop {
  animation: t-check-circle-pop var(--duration-fast) var(--ease-smooth-out) forwards;
}

@utility animate-success-check {
  animation:
    t-check-fade var(--check-opacity-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) forwards,
    t-check-rotate var(--check-rotate-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) forwards,
    t-check-blur var(--check-blur-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) forwards,
    t-check-bob var(--check-bob-dur, 500ms) cubic-bezier(0.34, 1.35, 0.64, 1) forwards;
}

@utility animate-check-draw {
  animation: t-check-draw var(--check-path-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) var(--check-path-delay, 80ms) forwards;
}

@utility animate-digit-pop {
  animation: digit-pop-in var(--digit-dur, 500ms) cubic-bezier(0.34, 1.45, 0.64, 1) both;
}

@keyframes badge-pop-in {
  0% {
    transform: translate(-4px, 4px) scale(0);
    filter: blur(var(--blur-small, 2px));
    opacity: 0;
  }
  60% {
    transform: translate(0, 0) scale(1.15);
    filter: blur(0);
    opacity: 1;
  }
  100% {
    transform: translate(0, 0) scale(1);
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes error-shake {
  0% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(calc(var(--shake-distance, 6px) * -1));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  40% {
    transform: translateX(var(--shake-overshoot, 4px));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  60% {
    transform: translateX(calc(var(--shake-overshoot, 4px) * -0.5));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  80% {
    transform: translateX(calc(var(--shake-overshoot, 4px) * 0.25));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  100% {
    transform: translateX(0);
  }
}

@keyframes text-reveal-rise {
  from {
    opacity: 0;
    transform: translateY(var(--distance-medium, 12px));
    filter: blur(var(--blur-medium, 3px));
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes step-slide-forward {
  from {
    opacity: 0;
    transform: translateX(var(--distance-base, 8px));
    filter: blur(var(--blur-medium, 3px));
  }
  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}

@keyframes step-slide-backward {
  from {
    opacity: 0;
    transform: translateX(calc(var(--distance-base, 8px) * -1));
    filter: blur(var(--blur-medium, 3px));
  }
  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}

@keyframes roll-up {
  from {
    opacity: 0;
    transform: translateY(4px);
    filter: blur(1px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes roll-down {
  from {
    opacity: 0;
    transform: translateY(-4px);
    filter: blur(1px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes t-check-circle-pop {
  0% {
    transform: scale(0.85);
    opacity: 0;
  }
  50% {
    transform: scale(1.05);
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes t-check-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes t-check-rotate {
  from {
    transform: rotate(var(--check-rotate-from, 80deg));
  }
  to {
    transform: rotate(0deg);
  }
}

@keyframes t-check-blur {
  from {
    filter: blur(var(--check-blur-from, 10px));
  }
  to {
    filter: blur(0px);
  }
}

@keyframes t-check-bob {
  from {
    transform: translateY(var(--check-y-amount, 40px));
  }
  to {
    transform: translateY(0);
  }
}

@keyframes t-check-draw {
  from {
    stroke-dashoffset: 26;
  }
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes digit-pop-in {
  0% {
    transform: translate(
      calc(var(--digit-distance, 8px) * var(--digit-dir-x, 0)),
      calc(var(--digit-distance, 8px) * var(--digit-dir-y, 1))
    );
    opacity: 0;
    filter: blur(var(--digit-blur, 2px));
  }
  100% {
    transform: translate(0, 0);
    opacity: 1;
    filter: blur(0);
  }
}

/* Standardized Type Scale Utility Classes */
@utility text-display-lg {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  text-wrap: balance;
}

@utility text-headline-lg {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 600;
  line-height: 1.25;
  text-wrap: balance;
}

@utility text-headline-md {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.35;
  text-wrap: balance;
}

@utility text-headline-sm {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.4;
  text-wrap: balance;
}

@utility text-body-lg {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 1.55;
  text-wrap: pretty;
}

@utility text-body-md {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
  text-wrap: pretty;
}

@utility text-label-lg {
  font-family: var(--font-label);
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: 0.01em;
}

@utility text-label-md {
  font-family: var(--font-label);
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: 0.01em;
}

@utility text-label-sm {
  font-family: var(--font-label);
  font-size: 0.75rem;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: 0.03em;
}

/* Global Heading & Body Text-Wrap Defaults */
h1, h2, h3, h4, h5, h6 {
  text-wrap: balance;
}

p, li {
  text-wrap: pretty;
}

/* Long-Form Content Rhythm (shadcn Typeset container system) */
.typeset {
  --typeset-font-body: var(--font-sans);
  --typeset-font-heading: var(--font-heading);
  --typeset-font-mono: var(--font-mono);
  --typeset-size: 1em;
  --typeset-leading: 1.5;
  --typeset-flow: 1.25em;

  font-family: var(--typeset-font-body);
  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  max-width: 40rem;
}

.typeset h1, .typeset h2, .typeset h3, .typeset h4 {
  font-family: var(--typeset-font-heading);
  font-weight: 600;
  line-height: 1.25;
  margin-top: calc(var(--typeset-flow) * 1.2);
  margin-bottom: calc(var(--typeset-flow) * 0.5);
  color: var(--on-surface);
  text-wrap: balance;
}

.typeset h1 {
  font-size: 1.875em;
}

.typeset h2 {
  font-size: 1.5em;
}

.typeset h3 {
  font-size: 1.25em;
}

.typeset h4 {
  font-size: 1.125em;
}

.typeset p, .typeset ul, .typeset ol {
  margin-top: 0;
  margin-bottom: var(--typeset-flow);
  color: var(--on-surface-variant);
  text-wrap: pretty;
}

/* Typeset opt-out isolation for embedded cards & interactive primitives */
.typeset .not-typeset,
.typeset [data-not-typeset] {
  margin-top: var(--typeset-flow);
  margin-bottom: var(--typeset-flow);
  font-size: 1rem;
  line-height: normal;
}

.typeset .not-typeset p,
.typeset [data-not-typeset] p {
  margin-bottom: 0;
}

.typeset-chat {
  --typeset-flow: 1em;
  --typeset-leading: 1.5;
}

.typeset-guide {
  --typeset-size: 1.125em;
  --typeset-leading: 1.55;
  --typeset-flow: 1.5em;
}

.typeset-large {
  --typeset-size: 1.25em;
  --typeset-leading: 1.8;
  --typeset-flow: 1.75em;
}
